const input = $input.first().json;
const dados = input.dados_roteador ? JSON.parse(input.dados_roteador) : {};
const detectados = dados.dados_detectados || {};

return [{
  json: {
    remotejid: input.remotejid,
    mensagem: input.mensagem,
    protocolo_detectado: detectados.protocolo || null,
    cpf_detectado: detectados.cpf || null
  }
}];

return [{
  json: {
    responder_cidadao: 'Para consultar sua manifestação, informe o número do protocolo.\nSe não tiver o número, posso buscar pelo seu CPF.'
  }
}];

const items = $input.all();

if (!items || items.length === 0 || !items[0].json.protocolo) {
  return [{
    json: {
      responder_cidadao: 'Não encontrei nenhuma manifestação com esse dado. Verifique o número e tente novamente.\nSe precisar de ajuda, posso transferir para um atendente.'
    }
  }];
}

const d = items[0].json;
const statusMap = {
  'AGUARDANDO_ANONIMO': 'Em coleta de dados',
  'AGUARDANDO_NOME': 'Em coleta de dados',
  'AGUARDANDO_DEMANDA': 'Em coleta de dados',
  'AGUARDANDO_LOCALIZACAO': 'Em coleta de dados',
  'AGUARDANDO_DATA': 'Em coleta de dados',
  'AGUARDANDO_DETALHES': 'Em coleta de dados',
  'AGUARDANDO_CONFIRMACAO': 'Aguardando confirmação',
  'AGUARDANDO_DESCRICAO_DETALHADA': 'Em análise',
  'CONFIRMADO': 'Registrada',
  'EM_ANDAMENTO': 'Em andamento',
  'RESPONDIDA': 'Respondida',
  'ENCERRADA': 'Encerrada'
};

const statusLabel = statusMap[d.status] || d.status || 'Em processamento';
const tipoMap = { 'reclamacao': 'Reclamação', 'denuncia': 'Denúncia', 'elogio': 'Elogio', 'sugestao': 'Sugestão', 'solicitacao': 'Solicitação' };
const tipoLabel = tipoMap[d.tipo_manifestacao] || d.tipo_manifestacao || 'N/A';
const areaLabel = d.area ? d.area.charAt(0).toUpperCase() + d.area.slice(1) : 'N/A';

let msg = `*Protocolo:* ${d.protocolo}\n`;
msg += `*Status:* ${statusLabel}\n`;
msg += `*Tipo:* ${tipoLabel}\n`;
msg += `*Área:* ${areaLabel}\n`;
msg += `*Aberto em:* ${d.created_at ? new Date(d.created_at).toLocaleDateString('pt-BR') : 'N/A'}\n`;
msg += `*Assunto:* ${d.assunto || 'N/A'}`;

if (d.descricao_detalhada) {
  msg += `\n\n*Resposta:* ${d.descricao_detalhada}`;
}

msg += '\n\nPosso te ajudar com mais alguma coisa?';

return [{ json: { responder_cidadao: msg } }];
